using System.ComponentModel.DataAnnotations;
using Microsoft.EntityFrameworkCore;

public sealed record SagaStep(Guid SagaId, string Sku, int AvailableBefore);
public sealed class Item
{
    public string Sku { get; set; } = "";
    [ConcurrencyCheck] public int Available { get; set; }
}
public sealed class Reservation
{
    public Guid Id { get; set; }
    public string Sku { get; set; } = "";
    public int Quantity { get; set; }
    public bool Released { get; set; }
}
public sealed class InventoryDb(DbContextOptions<InventoryDb> options) : DbContext(options)
{
    public DbSet<Item> Items => Set<Item>();
    public DbSet<Reservation> Reservations => Set<Reservation>();
}
